SELECT DISTINCT d.DEPT_ID, it.device_code,IFNULL(id.device_name,it.device_name) device_name,it.province_id,it.city_id,it.town_code,it.county_id
from sys_dept d LEFT JOIN vm_organ_device_rel_t dt ON d.DEPT_ID = dt.dept_id
LEFT JOIN vm_device_info_t it ON it.device_code = dt.device_code
left join vm_order_devices od on it.device_code = od.device_code
LEFT JOIN vm_tenant_device_channel_rel_t id ON id.device_code = it.device_code and d.TENANT_ID = id.TENANT_ID and id.delete_flag='0'
AND od.industry_code = id.industry_code
WHERE it.delete_flag = '0' AND dt.TENANT_ID=#{tenantId}

    and  d.DEPT_ID=#{deptId}


    AND d.DEPT_ID IN

        #{item}


and dt.industry_code=#{industryCode} and  dt.device_type NOT IN(8,9,10,11,12,13)
   and od.ord_status IN(0,1,2) AND od.tenant_id=#{tenantId} and od.industry_code=#{industryCode}
${dataScope}

SELECT DISTINCT d.DEPT_ID, it.device_code,IFNULL(id.device_name,it.device_name) device_name,it.province_id,it.city_id,it.town_code,it.county_id
