    and  d.DEPT_ID=#{deptId}


    AND d.DEPT_ID IN

        #{item}


and od.ord_status IN(0,1,2) AND od.tenant_id=#{tenantId} and od.industry_code=#{industryCode} AND od.category_code=1
${dataScope}

