SELECT DISTINCT
                rt.DEPT_ID,
                rt.province_code province_id,
                rt.city_code     city_id,
                rt.county_code   county_id,
                rt.street_code   town_code
from vm_organ_street_rel_t rt
         LEFT JOIN sys_dept d ON rt.DEPT_ID = d.DEPT_ID
         left join vm_order_services_rel od on od.provice_code = rt.province_code
    and od.city_code = rt.city_code
    and od.county_code = rt.county_code
WHERE rt.delete_flag = '0' AND rt.category_code = 9
  and rt.TENANT_ID = #{tenantId}
  and rt.industry_code = #{industryCode}

    and rt.DEPT_ID = #{deptId}


    AND rt.DEPT_ID IN

