  and od.ord_status IN (0, 1, 2)
  AND od.tenant_id = #{tenantId}
  and od.industry_code = #{industryCode}
  AND od.service_code = 9
    ${dataScope}

SELECT DISTINCT d.DEPT_ID, it.device_code, IFNULL( id.device_name, it.device_name ) device_name, it.province_code AS province_id, it.city_code AS city_id, it.town_code, it.county_code county_id, (case when length(IFNULL(nrel.device_name, '')) = 0 then nest.device_name else nrel.device_name end ) uavNestName FROM sys_dept d LEFT JOIN vm_organ_device_rel_t dt ON d.DEPT_ID = dt.dept_id LEFT JOIN vm_uav_device_info_t it ON it.device_code = dt.device_code LEFT JOIN vm_order_uav_devices od ON it.device_code = od.device_code LEFT JOIN vm_tenant_device_common_rel_t id ON id.device_code = it.device_code AND d.TENANT_ID = id.TENANT_ID AND d.INDUSTRY_CODE = id.industry_code and id.device_type = 1 left join `vm_uav_nest_device_info` nest on it.uav_nest_code = nest.device_code left join vm_tenant_device_common_rel_t nrel on nrel.device_code = nest.device_code AND nrel.tenant_id = od.tenant_id and nrel.industry_code = od.industry_code and nrel.delete_flag = '0' and nrel.device_type = 4 WHERE it.delete_flag = '0' AND dt.device_type = 11 AND dt.TENANT_ID = #{tenantId} and dt.industry_code=#{industryCode}
and d.DEPT_ID=#{deptId}
AND d.DEPT_ID IN
#{item}
AND od.ord_status IN (0, 1, 2) AND od.tenant_id = #{tenantId} and od.industry_code=#{industryCode} ${dataScope}

