SELECT DISTINCT IFNULL( id.device_name, di.device_name ) device_name, di.device_code, di.province_code AS provinceId, di.city_code AS cityId, di.town_code, di.county_code AS countyId FROM vm_order_uav_nest_devices od LEFT JOIN vm_uav_nest_device_info di ON di.device_code = od.device_code LEFT JOIN vm_tenant_device_common_rel_t id ON id.device_code = di.device_code AND od.TENANT_ID = id.TENANT_ID AND od.industry_code = id.industry_code and id.device_type = 4 WHERE di.delete_flag = '0' AND od.ord_status IN (0, 1, 2) AND od.tenant_id = #{tenantId}
